from pathlib import Path
import pandas as pd
import matplotlib.pyplot as plt
from scipy import stats

# 1. SETTINGS & FILE PATHS
ROOT = Path(__file__).resolve().parents[2]

cbs_file = ROOT / "Data" / "86358NED_SelectieZonderStatSymbol_20261012151433.csv"
residuals_file = ROOT / "Generated_Data" / "residuals.csv"
output_image = ROOT / "Images" / "transport_poverty_boxplot.png"

# 2. LOAD RESIDUALS (Generated by Regression_analysis.py)
df_residuals = pd.read_csv(residuals_file)

# 3. LOAD CBS DATA & DETECT INCOME
cbs = pd.read_csv(cbs_file, sep=";", dtype="string")
cbs.columns = [c.strip() for c in cbs.columns]

# Zoek automatisch of er een kolom met 'inkomen' in de data zit
income_cols = [c for c in cbs.columns if "inkomen" in c.lower()]

if income_cols:
    income_col = income_cols[0]
    print(f"Gevonden inkomenskolom: {income_col}")
    cbs_sub = cbs[["Regioaanduiding/Codering (code)", income_col]].copy()
    cbs_sub.columns = ["bu_code", "income"]
    cbs_sub["bu_code"] = cbs_sub["bu_code"].str.strip()
    cbs_sub["income"] = pd.to_numeric(cbs_sub["income"], errors="coerce")
    df = df_residuals.merge(cbs_sub, on="bu_code", how="inner").dropna(subset=["income", "residual_z"])
else:
    print("Geen inkomenskolom aangetroffen in dit CBS-bestand.")
    print("Beschikbare kolommen zijn o.a.:", list(cbs.columns[:6]))
    df = pd.DataFrame()

# 4. STATISTICAL ANALYSIS & PLOTTING
if not df.empty:
    print("\nTransport Poverty Analysis")
    print("-" * 50)
    print(f"Neighborhoods analyzed with income data: {len(df)}")

    # Correlation between income and PT Residual
    pearson_r, p_val = stats.pearsonr(df["income"], df["residual_z"])
    print(f"\nPearson correlation (Income vs. PT Residual): r = {pearson_r:.3f} (p = {p_val:.3e})")

    # Compare average income
    under_served = df[df["low_for_density"] == True]
    adequately_served = df[df["low_for_density"] == False]

    mean_income_under = under_served["income"].mean() * 1000
    mean_income_adequate = adequately_served["income"].mean() * 1000

    print("\nAverage Income Comparison:")
    print(f"  Under-served neighborhoods (low PT for density): €{mean_income_under:,.0f}")
    print(f"  Adequately served neighborhoods:                 €{mean_income_adequate:,.0f}")

    # Figure: Boxplot
    output_image.parent.mkdir(exist_ok=True)
    fig, ax = plt.subplots(figsize=(8, 6))

    data_to_plot = [under_served["income"], adequately_served["income"]]
    labels = ["Under-served\n(Residual < -1 SD)", "Adequately served\n(Residual >= -1 SD)"]

    bp = ax.boxplot(
        data_to_plot, 
        labels=labels, 
        patch_artist=True,
        showfliers=False,
        medianprops={"color": "black", "linewidth": 1.5}
    )

    colors = ["#e53e3e", "#3182ce"] 
    for patch, color in zip(bp['boxes'], colors):
        patch.set_facecolor(color)
        patch.set_alpha(0.7)

    ax.set_ylabel("Average Income per Resident (x €1,000)")
    ax.set_title("Income Distribution: Under-served vs. Adequately Served Neighborhoods", fontweight="bold")
    ax.grid(axis="y", alpha=0.3)

    fig.tight_layout()
    fig.savefig(output_image, dpi=200, facecolor="white")
    plt.close(fig)

    print(f"\nSaved boxplot to: {output_image}")
else:
    print("\nConclusie voor het rapport: CBS 86358NED bevat geen inkomensdata.")
    print("De hypothese rondom transportarmoede wordt daarom kwalitatief besproken in de discussie.")
